@Bean
public ConsumerAwareRebalanceListener rebalanceListener() {
    return new ConsumerAwareRebalanceListener() {
        private long revokedAt;

        @Override
        public void onPartitionsRevokedBeforeCommit(Consumer<?, ?> c, Collection<TopicPartition> ps) {
            revokedAt = System.currentTimeMillis();
            log.warn("[리밸런싱] 반납 {}개 {}", ps.size(), ps);
        }

        @Override
        public void onPartitionsAssigned(Consumer<?, ?> c, Collection<TopicPartition> ps) {
            log.warn("[리밸런싱] 배정 {}개 멈춘 시간 {}ms",
                    ps.size(), System.currentTimeMillis() - revokedAt);
            meterRegistry.counter("kafka.rebalance").increment();
        }
    };
}
